function fullJustify(words: string[], maxWidth: number): string[] {
  const result: string[] = [];
  let i = 0;

  while (i < words.length) {
    // 1. Жадно набираем слова в строку [i, j):
    //    lettersLen — суммарная длина слов без пробелов
    let j = i;
    let lettersLen = 0;
    // Слово j помещается, если буквы + минимум по одному пробелу между словами <= maxWidth
    while (j < words.length && lettersLen + words[j].length + (j - i) <= maxWidth) {
      lettersLen += words[j].length;
      j++;
    }

    const count = j - i; // слов в строке
    const gaps = count - 1; // промежутков между ними
    let line: string;

    if (j === words.length || gaps === 0) {
      // 2a. Последняя строка или одно слово — выравнивание по левому краю
      line = words.slice(i, j).join(' ');
      line += ' '.repeat(maxWidth - line.length);
    } else {
      // 2b. Выравнивание по ширине: делим пробелы между промежутками
      const spaces = maxWidth - lettersLen;
      const base = Math.floor(spaces / gaps); // минимум в каждом промежутке
      const extra = spaces % gaps; // первые extra промежутков получают +1

      line = '';
      for (let k = 0; k < count; k++) {
        line += words[i + k];
        if (k < gaps) {
          line += ' '.repeat(base + (k < extra ? 1 : 0));
        }
      }
    }

    result.push(line);
    i = j;
  }

  return result;
}

// Время: O(n · maxWidth) — каждая строка собирается за O(maxWidth), строк не больше n
// Память: O(maxWidth) на текущую строку (не считая ответа)
